const searchParams=new URLSearchParams(location.search);
const guestParams={adults:searchParams.get('adults')||'1',children:searchParams.get('children')||'0',rooms:searchParams.get('rooms')||'1'};
const resultsGuestLabel=document.querySelector('.search-guests');
const resultsPlural=(value,one,few,many)=>{const mod10=value%10,mod100=value%100;return mod10===1&&mod100!==11?one:mod10>=2&&mod10<=4&&(mod100<12||mod100>14)?few:many};
const updateResultsGuests=()=>{const adults=Number(guestParams.adults),children=Number(guestParams.children);resultsGuestLabel.innerHTML=`${adults} ${resultsPlural(adults,'взрослый','взрослых','взрослых')}${children?` · ${children} ${resultsPlural(children,'ребёнок','ребёнка','детей')}`:''} <img src="assets/arrow-down-fill-16.svg" alt="">`;document.querySelectorAll('.results-guests-popover [data-kind]').forEach(row=>{const value=Number(guestParams[row.dataset.kind]);row.querySelector('output').textContent=String(value);row.querySelector('[data-result-step="-1"]').disabled=value<=(row.dataset.kind==='children'?0:1);row.querySelector('[data-result-step="1"]').disabled=value>=9});document.querySelectorAll('.hotel-title a').forEach(link=>{const url=new URL(link.href,location.href);url.searchParams.set('adults',guestParams.adults);url.searchParams.set('children',guestParams.children);url.searchParams.set('rooms',guestParams.rooms);link.href=url.href})};
if(resultsGuestLabel){const popover=document.createElement('div');popover.className='results-guests-popover';popover.hidden=true;popover.innerHTML=`<div data-kind="adults"><span><b>Взрослые</b><small>От 18 лет</small></span><div><button type="button" data-result-step="-1">−</button><output></output><button type="button" data-result-step="1">+</button></div></div><div data-kind="children"><span><b>Дети</b><small>До 17 лет</small></span><div><button type="button" data-result-step="-1">−</button><output></output><button type="button" data-result-step="1">+</button></div></div><div data-kind="rooms"><span><b>Номера</b></span><div><button type="button" data-result-step="-1">−</button><output></output><button type="button" data-result-step="1">+</button></div></div>`;resultsGuestLabel.after(popover);resultsGuestLabel.addEventListener('click',()=>{popover.hidden=!popover.hidden});popover.addEventListener('click',event=>{const step=event.target.closest('[data-result-step]');if(!step)return;const kind=step.closest('[data-kind]').dataset.kind;const min=kind==='children'?0:1;guestParams[kind]=String(Math.max(min,Math.min(9,Number(guestParams[kind])+Number(step.dataset.resultStep))));updateResultsGuests()});document.addEventListener('click',event=>{if(!event.target.closest('.search-guests')&&!event.target.closest('.results-guests-popover'))popover.hidden=true})}
const hotels=[
 {name:'Москва Красносельская',url:'hotel.html',address:'Москва, улица Верхняя Красносельская, 11Ас4 · 3,4 км до центра',stars:3,photo:'assets/hotel-figma/image-3.png',count:'10 фото',air:'Шереметьево 26 км · Внуково 32 км · Остафьево 32 км',rail:'Ярославский 1 км · Ленинградский 1 км · Казанский 1,4 км',metro:['Красносельская 0,3 км','Комсомольская 0,5 км'],price:'33 000 ₽',more:'Показать ещё 4 предложения'},
 {name:'Mövenpick Москва Таганская',address:'Москва, улица Земляной Вал, 70 · 2,7 км до центра',stars:4,photo:'assets/hotel/hotel-exterior.png',count:'5 фото',rail:'Павелецкий 1 км · Киевский 4 км',metro:['Таганская 0,3 км','Марксистская 0,5 км'],price:'33 000 ₽',more:'Показать ещё 4 предложения'},
 {name:'FortEstate',address:'Москва, проспект Вернадского 41 строение 1 · 15,4 км до центра',stars:0,photo:'assets/hotel-figma/image-9.png',count:'12 фото',air:'Внуково 15 км · Шереметьево 33 км · Домодедово 37 км',rail:'Киевский 10 км · Павелецкий 12 км · Курский 15 км',metro:['Новаторская 0,9 км','Проспект Вернадского 0,98 км'],price:'130 400 ₽',more:'Показать ещё 8 предложений'}
];
const starSet=count=>`<span class="stars">${Array.from({length:5},(_,i)=>`<img class="${i>=count?'muted':''}" src="assets/hotel/star.svg" alt="">`).join('')}</span>`;
const transport=h=>`<div class="transport">${h.air?`<div><img src="assets/hotel/flight.svg" alt="">${h.air}</div>`:''}${h.rail?`<div><img src="assets/hotel/train.svg" alt="">${h.rail}</div>`:''}<div><i class="metro-dot"></i>${h.metro[0]}<i class="metro-dot yellow"></i>${h.metro[1]}</div></div>`;
const hotelTemplate=(h,i)=>`<article class="hotel-result"><div class="hotel-head hotel-summary"><div class="hotel-summary__content"><div class="hotel-title"><h2>${h.url?`<a href="${h.url}">${h.name}</a>`:h.name}</h2>${h.stars?starSet(h.stars):''}<button aria-label="Ещё"><img src="assets/hotel/more-16.svg" alt=""></button></div><p>${h.address}</p>${transport(h)}</div><div class="hotel-photo"><img src="${h.photo}" alt="${h.name}"><span class="photo-count">${h.count}</span></div></div><div class="room-card"><div class="room-snippet"><img src="assets/hotel-figma/image-2.png" alt="Номер"><div class="room-copy"><h3>Стандарт двухместный 1 кровать</h3><div class="room-meta"><span><img src="assets/hotel/area.svg" alt="">25м²</span><span><img src="assets/hotel/bed.svg" alt="">Двуспальная</span><span><img src="assets/hotel/bath.svg" alt="">В номере</span></div></div><button class="room-heart"><img src="assets/hotel/heart-new-16.svg" alt="В подборку"></button></div><div class="primary-offer" data-price="${h.price}"></div><div class="extra-offers" hidden></div><button class="more-offers" data-index="${i}"><span>${h.more}</span><img src="assets/arrow-down-fill-16.svg" alt=""></button></div></article>`;
document.querySelector('#hotels').innerHTML=hotels.map(hotelTemplate).join('');
updateResultsGuests();
document.querySelectorAll('.primary-offer').forEach(root=>HotelOfferWidget.render(root,{...HotelOfferWidget.get('full-penalty'),price:root.dataset.price}));
document.querySelector('#hotels').addEventListener('click',event=>{const choose=event.target.closest('.offer-booking button');if(!choose)return;event.stopImmediatePropagation();const card=choose.closest('.hotel-result');const params=new URLSearchParams({hotel:card.querySelector('.hotel-title h2').textContent.trim(),address:card.querySelector('.hotel-summary__content>p').textContent.trim(),price:choose.closest('.hotel-offer-widget').querySelector('.offer-price-main strong').textContent.trim(),...guestParams});window.location.href=`booking.html?${params}`});
document.querySelectorAll('.more-offers').forEach(button=>{const card=button.closest('.hotel-result');const extra=card.querySelector('.extra-offers');const basePrice=hotels[button.dataset.index].price;const offers=[{...HotelOfferWidget.get('with-food'),price:basePrice},{...HotelOfferWidget.get('free-cancel'),price:basePrice},{...HotelOfferWidget.get('full-penalty'),price:basePrice},{...HotelOfferWidget.get('no-food-no-upsell'),price:basePrice}];extra.innerHTML=offers.map(HotelOfferWidget.markup).join('');HotelOfferWidget.bind(extra);button.addEventListener('click',()=>{const opening=extra.hidden;extra.hidden=!opening;card.classList.toggle('open',opening);button.classList.toggle('is-open',opening);button.querySelector('span').textContent=opening?'Скрыть предложения':hotels[button.dataset.index].more})});
document.querySelector('.search-place button').addEventListener('click',()=>document.querySelector('.search-place input').value='');
document.querySelectorAll('.level-chips button').forEach(button=>button.addEventListener('click',()=>button.classList.toggle('selected')));
const sortButton=document.querySelector('#sortButton');let sortRecommended=true;sortButton.addEventListener('click',()=>{sortRecommended=!sortRecommended;sortButton.querySelector('.sort-label').textContent=sortRecommended?'Рекомендуемая':'По цене'});
document.querySelector('.results-search form').addEventListener('submit',event=>event.preventDefault());
document.querySelectorAll('.results-pagination nav button').forEach(button=>button.addEventListener('click',()=>{if(/^\d+$/.test(button.textContent)){document.querySelectorAll('.results-pagination nav button').forEach(x=>x.classList.remove('active'));button.classList.add('active')}}));
document.querySelectorAll('.filters-card h3>span').forEach(span=>{span.className='filter-chevron';span.innerHTML='<img src="assets/arrow-down-fill-16.svg" alt="">'});
document.querySelectorAll('.filters-card h3>small').forEach(icon=>{icon.className='filter-help';icon.innerHTML='<img src="assets/hotel/info-new-16.svg" alt="">'});
document.querySelectorAll('.filters-card section').forEach(section=>{const heading=section.querySelector('h3');if(!heading)return;heading.tabIndex=0;heading.setAttribute('role','button');heading.setAttribute('aria-expanded','true');const toggle=()=>{const collapsed=section.classList.toggle('is-collapsed');heading.setAttribute('aria-expanded',String(!collapsed))};heading.addEventListener('click',toggle);heading.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggle()}})});
const drawer=document.querySelector('#roomDrawer');const closeDrawer=()=>{drawer.hidden=true;document.body.classList.remove('room-drawer-open')};const openDrawer=()=>{drawer.hidden=false;document.body.classList.add('room-drawer-open');drawer.querySelector('.room-drawer-close').focus()};document.querySelectorAll('.room-snippet').forEach(snippet=>{snippet.tabIndex=0;snippet.setAttribute('role','button');snippet.setAttribute('aria-label','Открыть информацию о номере');snippet.addEventListener('click',event=>{if(!event.target.closest('.room-heart'))openDrawer()});snippet.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('.room-heart')){event.preventDefault();openDrawer()}})});drawer.querySelector('.room-drawer-close').addEventListener('click',closeDrawer);drawer.querySelector('.room-drawer-backdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!drawer.hidden)closeDrawer()});
